function dspNegotiationError(statusCode, code, reasons, providerPid, consumerPid) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'],
        '@type': 'ContractNegotiationError',
        providerPid: providerPid || 'urn:facis:dsp:unknown',
        consumerPid: consumerPid || 'urn:facis:dsp:unknown',
        code: code,
        reason: reasons
    };
    return msg;
}

// NO auto-finalize. The negotiation is created REQUESTED; the
// negotiation.permit policy gate (dsp-neg-check-permit) is the ONLY place that
// can move it to FINALIZED or TERMINATED.
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (!body.counterparty || !body.offerId) {
    return [null, dspNegotiationError(422, 'invalid_request', ['counterparty and offerId are required'], null, body.consumerPid)];
}
const now = new Date().toISOString();
const negId = 'neg-' + crypto.randomBytes(6).toString('hex');
const counterparty = (msg.identity && msg.identity.did) ? msg.identity.did : body.counterparty;
const negotiation = {
    id: negId,
    providerPid: negId,
    consumerPid: body.consumerPid || negId,
    state: 'REQUESTED',
    offerId: body.offerId,
    dataset: body.dataset || null,
    purpose: body.purpose || null,
    constraints: Array.isArray(body.constraints) ? body.constraints : [],
    counterparty: counterparty,
    createdAt: now,
    updatedAt: now
};
const negs = global.get('negotiations') || {};
negs[negId] = negotiation;
global.set('negotiations', negs);

msg._negId = negId;
msg.payload = { negotiationId: negId, state: 'REQUESTED' };
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 202;
return [msg, null];

function dspNegotiationError(statusCode, code, reasons, providerPid, consumerPid) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'],
        '@type': 'ContractNegotiationError',
        providerPid: providerPid || 'urn:facis:dsp:unknown',
        consumerPid: consumerPid || 'urn:facis:dsp:unknown',
        code: code,
        reason: reasons
    };
    return msg;
}

// build the policy-engine input for negotiation.permit
// (OPA data API shape: POST /v1/data/facis/negotiation/permit, body {input}).
const negs = global.get('negotiations') || {};
const neg = negs[msg._negId];
if (!neg) return [null, dspNegotiationError(500, 'internal', ['negotiation ' + msg._negId + ' not in store'], null, null)];
const base = (env.get('OCM_POLICY_URL') || '').replace(/\/+$/, '');
if (!base) return [null, dspNegotiationError(500, 'config_missing', ['OCM_POLICY_URL not set — fail closed'], null, null)];
msg._iamOrigPayload = msg.payload;
msg.url = base + '/v1/data/facis/negotiation/permit';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    input: {
// the permit subject is the verified participant — did AND participantRoles
// from msg.identity (set by iam.verify from the VC credentialSubject). The rego
// checks roles against data.facis.vocabulary.participant_roles.
        subject: { did: (msg.identity && msg.identity.did) || neg.counterparty, roles: (msg.identity && Array.isArray(msg.identity.roles)) ? msg.identity.roles : [] },
        action: 'negotiation.permit',
        resource: { negotiationId: neg.id, offerId: neg.offerId, dataset: neg.dataset },
        context: { purpose: neg.purpose, constraints: neg.constraints }
    }
};
return [msg, null];

function dspNegotiationError(statusCode, code, reasons, providerPid, consumerPid) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'],
        '@type': 'ContractNegotiationError',
        providerPid: providerPid || 'urn:facis:dsp:unknown',
        consumerPid: consumerPid || 'urn:facis:dsp:unknown',
        code: code,
        reason: reasons
    };
    return msg;
}

// permit -> FINALIZED, deny -> TERMINATED WITH a reason. The
// decision is applied to the persisted store (global negotiations -> Postgres
// via the persist link-out); the HTTP response carries the final state.
const decision = msg.payload && msg.payload.result;
if ('_iamOrigPayload' in msg) { msg.payload = msg._iamOrigPayload; delete msg._iamOrigPayload; }
const negs = global.get('negotiations') || {};
const neg = negs[msg._negId];
if (!neg) return [null, null, dspNegotiationError(500, 'internal', ['negotiation missing'], null, null)];
if (!decision || typeof decision.allow !== 'boolean') {
    // fail closed: policy unreachable -> 502, state stays REQUESTED
    return [null, null, dspNegotiationError(502, 'policy_unreachable', ['negotiation.permit engine did not answer a boolean verdict'], neg.providerPid, neg.consumerPid)];
}
const now = new Date().toISOString();
if (decision.allow === true) {
    neg.state = 'FINALIZED';
    neg.agreementId = 'agr-' + crypto.randomBytes(6).toString('hex');
    neg.updatedAt = now;
    negs[neg.id] = neg;
    global.set('negotiations', negs);
    msg.statusCode = 200;
    msg.payload = neg;
    msg.headers = { 'Content-Type': 'application/json' };
    return [msg, null, null];
}
neg.state = 'TERMINATED';
neg.terminationReason = decision.reason || 'denied by negotiation.permit';
neg.updatedAt = now;
negs[neg.id] = neg;
global.set('negotiations', negs);
msg.statusCode = 200;
msg.payload = neg;
msg.headers = { 'Content-Type': 'application/json' };
return [null, msg, null];

function dspNegotiationError(statusCode, code, reasons, providerPid, consumerPid) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'],
        '@type': 'ContractNegotiationError',
        providerPid: providerPid || 'urn:facis:dsp:unknown',
        consumerPid: consumerPid || 'urn:facis:dsp:unknown',
        code: code,
        reason: reasons
    };
    return msg;
}

const negs = global.get('negotiations') || {};
const id = msg.req.params.id;
const found = negs[id];
if (!found) {
    dspNegotiationError(404, 'not_found', ['Negotiation ' + id + ' not found'], id, id);
} else {
    msg.statusCode = 200;
    msg.payload = found;
}
msg.headers = { 'Content-Type': 'application/json' };
return msg;

function dspNegotiationError(statusCode, code, reasons, providerPid, consumerPid) {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        '@context': ['https://w3id.org/dspace/2025/1/context.jsonld'],
        '@type': 'ContractNegotiationError',
        providerPid: providerPid || 'urn:facis:dsp:unknown',
        consumerPid: consumerPid || 'urn:facis:dsp:unknown',
        code: code,
        reason: reasons
    };
    return msg;
}

const negs = global.get('negotiations') || {};
const id = msg.req.params.id;
const neg = negs[id];
if (!neg) {
    dspNegotiationError(404, 'not_found', ['Negotiation ' + id + ' not found'], id, id);
    msg.headers = { 'Content-Type': 'application/json' };
    return [msg, null];
}
const now = new Date().toISOString();
const terminated = Object.assign({}, neg, { state: 'TERMINATED', updatedAt: now });
negs[id] = terminated;
global.set('negotiations', negs);
msg.payload = terminated;
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 200;
// the termination is persisted (output 1 -> dsp.persist.negotiations)
return [msg, msg];
